<?php
$from=is_string($_GET['from']??null)?$_GET['from']:date('Y-m-01');$to=is_string($_GET['to']??null)?$_GET['to']:date('Y-m-d');
foreach([$from,$to] as $date){$d=DateTimeImmutable::createFromFormat('!Y-m-d',$date);if(!$d||$d->format('Y-m-d')!==$date){echo '<p class="error">Invalid date range.</p>';return;}}
if($from>$to){echo '<p class="error">Start date must precede end date.</p>';return;}
$bar=(int)run("SELECT COALESCE(SUM(quantity*unit_price),0) FROM sales WHERE status='Paid' AND substr(paid_at,1,10) BETWEEN ? AND ?",[$from,$to])->fetchColumn();$event=(int)run('SELECT COALESCE(SUM(amount),0) FROM payments WHERE substr(created_at,1,10) BETWEEN ? AND ?',[$from,$to])->fetchColumn();$cost=(int)run('SELECT COALESCE(SUM(quantity*unit_cost),0) FROM purchases WHERE substr(created_at,1,10) BETWEEN ? AND ?',[$from,$to])->fetchColumn();$events=(int)run('SELECT COUNT(*) FROM reservations WHERE date BETWEEN ? AND ?',[$from,$to])->fetchColumn();
?>
<section class="panel"><form method="get" class="report-toolbar"><input type="hidden" name="page" value="reports"><?php input_field('from','From','date',$from);input_field('to','To','date',$to); ?><button class="button">Apply period</button><button type="button" class="button" data-print>Print report</button><a class="text-link" href="../export.php?from=<?= esc($from) ?>&to=<?= esc($to) ?>">Download CSV ↗</a></form><p class="help">Period: <?= esc($from.' to '.$to) ?>. Bar collections use payment dates; event collections use recorded payment dates. Product sales use order dates. Reservation counts use event dates.</p></section><?php $unknown=run("SELECT COUNT(*) AS count,COALESCE(SUM(quantity*unit_price),0) AS amount FROM sales WHERE status='Paid' AND paid_at IS NULL")->fetch();if((int)$unknown['count']>0): ?><section class="panel"><p class="help"><?= (int)$unknown['count'] ?> historical paid sale(s), totaling <?= money($unknown['amount']) ?>, have an unknown collection date. They are excluded from period bar collections and retained in all-time recorded collections.</p></section><?php endif; ?><div class="metrics"><?php foreach([['Bar collections',money($bar)],['Event collections',money($event)],['Received purchases',money($cost)],['Scheduled events',$events]] as [$label,$value]): ?><div class="metric"><p><?= $label ?></p><strong><?= $value ?></strong></div><?php endforeach; ?></div><div class="grid2"><section class="panel"><h2>Reservation status</h2><?php $statuses=run('SELECT status,COUNT(*) AS count FROM reservations WHERE date BETWEEN ? AND ? GROUP BY status',[$from,$to])->fetchAll();foreach($statuses as $r): ?><p style="margin-bottom:5px"><?= esc($r['status']) ?> <strong style="float:right"><?= $r['count'] ?></strong></p><div class="trend-bar"><span style="width:<?= $events?round($r['count']/$events*100):0 ?>%"></span></div><?php endforeach;if(!$statuses): ?><p class="help">No events in this period.</p><?php endif; ?></section><section class="panel"><h2>Products sold</h2><?php $products=run('SELECT p.name,SUM(s.quantity) AS quantity,SUM(s.quantity*s.unit_price) AS sales FROM sales s JOIN products p ON p.id=s.product_id WHERE substr(s.created_at,1,10) BETWEEN ? AND ? GROUP BY p.id ORDER BY sales DESC',[$from,$to])->fetchAll();foreach($products as &$r)$r['sales']=money($r['sales']);unset($r);table_view($products,['name'=>'Product','quantity'=>'Quantity','sales'=>'Recorded sales']); ?></section></div><section class="panel"><h2>Period reservations</h2><?php table_view(run('SELECT reference,name,event_type,date,status FROM reservations WHERE date BETWEEN ? AND ? ORDER BY date',[$from,$to])->fetchAll(),['reference'=>'Reference','name'=>'Customer','event_type'=>'Occasion','date'=>'Date','status'=>'Status']); ?><p class="help">Operational reports only. Collections are not a profit calculation or statutory accounting report.</p></section>
